 --mari-tokens-version: 1; --radius: 0.875rem; --mari-font-ui: system-ui, sans-serif; --mari-font-heading: Georgia, serif; --mari-font-chat: system-ui, sans-serif; --mari-message-measure: 70ch;
 --mari-selected-tint: var(--primary); --mari-page-veil: var(--background); --mari-top-bar-plate: var(--card); --mari-top-bar-plate-radius: 8px;
 --mari-app-backdrop: url("theme:harbor-day-background.webp"); --mari-top-bar-bg: url("theme:harbor-day-header.webp") center / cover no-repeat;
 --mari-app-backdrop-position: center; --mari-app-backdrop-size: cover;
 /* Always supply the full background layer, including in clear weather. */
 --mari-app-backdrop-layers: var(--mari-app-backdrop) center / cover no-repeat;
 --mari-dialogue-color: var(--card-foreground);
 --ov-text: var(--foreground); --ov-muted: var(--muted-foreground); --ov-dim: var(--muted-foreground); --ov-line: var(--border); --ov-accent: var(--primary); --ov-hover: var(--accent); --ov-active-bg: var(--secondary);
 --mari-weather-style: smooth; --mari-weather-amount: 0.65; --mari-weather-speed: 0.8; --mari-weather-strength: 1; --mari-weather-tint-strength: 0.65; --mari-weather-rain-color: #5896b3; --mari-weather-rain-length: 1.3; --mari-weather-snow-color: #d8eaf1; --mari-weather-snow-size: 1.1; --mari-weather-fog-color: #b6cbd0; --mari-weather-sun-color: #ffe2a1; --mari-weather-moon-color: #ffedc9;
}
:root, :root[data-theme="light"], :root[data-mari-sky="day"], :root[data-mari-sky="dawn"] {
 --background: #eaf3f2; --foreground: #173c48; --card: #fffaf0; --card-foreground: #173c48; --popover: #fffaf0; --popover-foreground: #173c48; --primary: #086780; --primary-foreground: #ffffff; --secondary: #d9e9e8; --secondary-foreground: #173c48; --muted: #e3edeb; --muted-foreground: #4c6870; --accent: #cce8ea; --accent-foreground: #173c48; --border: #8aa7ac; --input: #7899a0; --ring: #086780; --sidebar: #f3f3e9; --sidebar-foreground: #173c48; --sidebar-border: #8aa7ac; --sidebar-accent: #d9e9e8; --sidebar-accent-foreground: #173c48; --destructive: #a52f2f; --destructive-foreground: #ffffff;
}
:root[data-theme="dark"]:not([data-mari-sky="day"]):not([data-mari-sky="dawn"]), :root[data-mari-sky="night"], :root[data-mari-sky="dusk"] {
 --background: #101e28; --foreground: #f5ead5; --card: #1a2b34; --card-foreground: #f5ead5; --popover: #1a2b34; --popover-foreground: #f5ead5; --primary: #edbc77; --primary-foreground: #29200f; --secondary: #30424a; --secondary-foreground: #f5ead5; --muted: #253942; --muted-foreground: #bfd0cf; --accent: #3c4e54; --accent-foreground: #fff0d6; --border: #697e80; --input: #839695; --ring: #edbc77; --sidebar: #15252e; --sidebar-foreground: #f5ead5; --sidebar-border: #697e80; --sidebar-accent: #30424a; --sidebar-accent-foreground: #f5ead5; --destructive: #ffb0a1; --destructive-foreground: #331a18;
 --mari-app-backdrop: url("theme:harbor-night-background.webp"); --mari-top-bar-bg: url("theme:harbor-night-header.webp") center / cover no-repeat; --mari-weather-rain-color: #a6c6d4;
}
:root[data-mari-weather="rain"], :root[data-mari-weather="storm"] { --mari-weather-tint-strength: 0.85; --mari-app-backdrop-layers: linear-gradient(#102c4866,#102c4866), var(--mari-app-backdrop) center / cover no-repeat; }
:root[data-mari-weather="snow"] { --mari-app-backdrop-layers: linear-gradient(#d7edf333,#aecbd144), var(--mari-app-backdrop) center / cover no-repeat; }
:root[data-mari-weather="fog"] { --mari-weather-tint-strength: 0.95; --mari-app-backdrop-layers: linear-gradient(#b6cbd077,#b6cbd0aa), var(--mari-app-backdrop) center / cover no-repeat; }
[data-mari-part="page"], [data-mari-part="home-widget"], .mari-window, .mari-drawer, [data-mari-part="message"], [data-mari-part="composer"] { background: var(--card); color: var(--card-foreground); border: 1px solid var(--border); border-radius: 14px; box-shadow: 0 5px 18px -10px #06192366; }
:where(button,input,select,textarea) { border-radius: 8px; }
:where(input,select,textarea) { background-color: var(--card); color: var(--foreground); border-color: var(--input); }
:where(input,textarea)::placeholder { color: var(--muted-foreground); opacity: 1; }
:where(button,input,select,textarea,a):focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
@media (hover:hover) { [data-mari-part="home-widget"]:hover { border-color: var(--primary); } }
/* Native phone layout, toolbar heights, and accessibility overrides remain intact. */

